def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release (everything after '-')
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            prerelease_identifiers = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_identifiers.append((0, int(part)))
                else:
                    prerelease_identifiers.append((1, part))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, v = item
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # For sorting: version with pre-release sorts before version without
        # We represent this by (major, minor, patch, has_prerelease, prerelease_identifiers, index)
        # has_prerelease: False (0) if no pre-release (sorts after), True (1) if has pre-release (sorts before)
        # So we use: False means it comes after, so we invert: prerelease_identifiers is None -> (1, [])
        # prerelease_identifiers is not None -> (0, prerelease_identifiers)

        if prerelease_identifiers is None:
            # No pre-release: sorts after version with pre-release
            prerelease_key = (1, [])
        else:
            # Has pre-release: sorts before version without pre-release
            prerelease_key = (0, prerelease_identifiers)

        return (major, minor, patch, prerelease_key, index)

    # Create list of (index, version) to maintain stability
    indexed_versions = list(enumerate(versions))

    # Sort using the key function
    sorted_indexed = sorted(indexed_versions, key=sort_key)

    # Extract just the version strings
    return [v for _, v in sorted_indexed]

